# 10-25 JB 결정(guide/handoff/jb_audit_1024/IMPL_review.md) — build4가 렌더 전에 적용 · 공통-8 줄 구조만 정리(JB 글자 그대로) · 공통-9 다음 문항 머리글·표지 줄 떼기
import re as _re
def _fx(old, *lines):
    """공통-8 한 건: old(JB 원문 그대로) → lines(화면 한 줄씩) — 줄바꿈·공백만 다르고 JB 글자는 그대로(여기서 확인).
    lines의 둘째 줄부터 강제 줄바꿈 표시(U+2063)를 붙여 reflow가 다시 잇지 않게 한다(10-25 — 옛 '»' 줄 앞 공백 300칸 우회는 없앰)."""
    new = '\n'.join([lines[0].lstrip('»')] + ['\u2063' + l.lstrip('»') for l in lines[1:]])   # 10-25 메인: 줄 앞 공백 300칸 우회 대신 강제 줄바꿈 표시(U+2063 — reflow가 앞 줄에 잇지 않고 지움) · '»'는 옛 표기(무시)
    assert _re.sub(r'[\s\u2063]+', '', old) == _re.sub(r'[\s\u2063]+', '', new), f'JBFIX 글자가 바뀜: {old[:30]!r}'
    return (old, new)
def _like(old, *tmpl):
    """다른 판의 같은 글(띄어쓰기만 다름)을 tmpl(줄 목록 — 위 _fx 꼴)과 같은 줄로 나눔 · 띄어쓰기는 old 그대로(줄 안의 줄바꿈만 공백으로)"""
    out, i = [], 0
    for t in tmpl:
        w = t.startswith('»'); n = len(_re.sub(r'\s+', '', t[1:] if w else t)); buf, c = '', 0
        while c < n:
            ch = old[i]; i += 1
            if ch.isspace():
                if buf and not buf.endswith(' '): buf += ' '
                continue
            buf += ch; c += 1
        out.append(('»' if w else '') + buf.strip())
    return _fx(old, *out)
